(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["ha"] = {"ui":{"skip":"Tsallake zuwa abubuwan shafin","back":"← Koma zuwa AI-gile","lang.button":"Harshe: {name}","lang.dialog":"Zaɓi harshe","lang.search":"Nemi harsuna","lang.none":"Babu harshen da ya dace","lang.notYet":"Ba a fassara {name} ba tukuna","theme.aria":"Canza tsakanin yanayin haske da duhu","theme.toLight":"Koma yanayin haske","theme.toDark":"Koma yanayin duhu","index.title":"AI-gile: ƙungiyar AI ɗinku ta masu shirye-shirye, a allo ɗaya","index.description":"AI-gile allon kanban ne don ƙungiyoyin AI masu rubuta lamba. Suna aiki yayin da kuke barci; ku kuwa kuna samun ɗan tarin abubuwa don yanke shawara, gwadawa da karɓa.","hero.logoAlt":"Alamar allon AI-gile","hero.h1.html":"Ƙungiyar AI ɗinku ta masu shirye-shirye, a allo&nbsp;ɗaya.","hero.alpha":"🐣 Pre-alpha a rufe","hero.alphaTitle":"Na farko ne kuma ba a gama ba: na gode da gwadawa!","hero.lede":"Suna ginawa yayin da kuke barci. Kuna farkawa zuwa ɗan tarin kaɗan: 'yan tambayoyi, 'yan abubuwan gwadawa, lu'u-lu'u mai shuɗi ɗaya ko biyu. Danna, karɓa, ku koma kofi ɗinku.","dl.windows":"Manhajar Windows","dl.browser":"Gudanar da shi a browser","dl.soon":"Nan ba da daɗewa ba","dl.notify":"🔔 Ku sanar da ni idan ya buɗe","dl.notifySmall":"Alpha ko beta","hero.secondary":"Agile, amma ƙungiyar ba ta taɓa buƙatar kofin tsaye na taro ba. (Duk da haka suna yin taron.)","pitch.h2":"AI-gile da kalmomi kamar yadda kuke so","pitch.lede":"Zaɓi tsayi, daga kalma ɗaya zuwa 144. Kowane tsayi bayaninsa ne na kansa, wanda aka rubuta don wannan girman. Ja maɓallin zamiya ko ku yi amfani da maɓallan kibiya.","pitch.rangeLabel":"Tsayi cikin kalmomi","pitch.dice":"🎲 wani sigar","pitch.words.one":"kalma {n}","pitch.words.other":"kalmomi {n}","pitch.letters.one":"harafi {n}","pitch.letters.other":"haruffa {n}","pitch.chars.one":"alama {n}","pitch.chars.other":"alamomi {n}","count.line.html.one":"kati {n} a allo yanzu","count.line.html.other":"kati {n} a allo yanzu","features.aria":"Abin da yake yi","f.pile.h":"Tari ɗaya a gare ku","f.pile.html":"<b>Gare ku</b> yana ɗauke da duk abin da ke jiran ku, a kowane aiki: tambayoyi, abubuwan gwadawa, ayyukan da mutum kaɗai zai iya yi. Layinku yana faɗin abin da ke gaba da tsawon lokacin da zai ɗauka.","f.sleep.h":"Ƙungiyoyi masu aiki yayin da kuke barci","f.sleep.p":"Kowane aiki yana da jagora da ƙungiyar wakilan AI. Ku yi sharhi a kan kati sai ƙungiyar ta farka, ta yi aikin, ta mayar da shi da matakan da gajiyayyen mutum zai iya bi.","f.tester.h":"Mai gwajin AI yana dubawa tukuna","f.tester.p":"Kafin wani abu ya zo gare ku, mai gwaji yana bin matakai a kwafin manhajar kuma yana nuna abin da ya gani, da hoton allo. Ku duba waɗanda suka yi nasara ku karɓa da danna ɗaya.","f.proof.h":"Shaida, ba alkawari ba","f.proof.p":"Kowace miƙawa tana nuna abin da ya canza: fayilolin, bambancin, hotunan allo. Ba sai kun buɗe kowace manhaja don ganin an gama ba.","f.chat.h":"Ku yi hira da jagororinku","f.chat.p":"Ginshiƙi irin na Discord: alama ɗaya ga kowane aiki, lu'u-lu'u masu shuɗi ga abin da ke buƙatar ku. Ku aika wa jagora ra'ayi; zai mayar da shi kati da shiri, tare da maɓallin ✅ Go.","f.tidy.h":"Yana tsara kansa","f.tidy.p":"Katuna masu alaƙa suna haɗuwa wuri ɗaya, ana gyara taken da suka ruɗe, kuma duba token yana sa lamba ta zama marar nauyi. Ƙarancin abubuwan da za a sauya tsakaninsu, ƙarancin tunani.","f.private.h":"Naku ne, a kwamfutarku","f.private.li1":"Allon yana aiki a injin ɗinku kuma yana amsa muku kaɗai.","f.private.li2":"DM na sirri tsakanin mutane an ɓoye su daga ƙarshe zuwa ƙarshe.","f.private.li3":"Babu asusu, babu masu bin diddigi, babu kuki.","f.lang.h":"A cikin harshenku","f.lang.p":"Harsuna sama da 120, daga Dutch, Welsh da Japananci zuwa na 'yan fashin teku, Yoda da Klingon, da saurin komawa Turanci don kalmomin masu shirye-shirye.","tl.aria":"Jerin lokaci daga tattaunawar farko zuwa taswirar gaba","tl.h2":"Daga tattaunawar farko zuwa abin da ke gaba","tl.lede":"Kwanaki da lokuta na gaske, a yankin lokacinku. Bayan yau shiri ne, ba tare da alƙawarin kwanan wata ba.","tl.today":"Yau","tl.planned":"a shirye","tl.cards.one":"kati {n}","tl.cards.other":"katuna {n}","join.h2":"Ku shiga","join.lede":"Ƙaramin mutum da wakilai masu haƙuri da yawa ne ke gina AI-gile. Na sirri ne a yanzu, a alpha a rufe tare da abokai. Kuna son gwadawa idan ya buɗe?","join.btn":"Yi rijistar sha'awa","join.small":"Za mu rubuto muku imel, ba wani abu ba","footer.tag":"AI-gile. Babu masu bin diddigi, babu kuki, babu kofin tsaye na taro.","footer.licence":"Lasisin kasuwanci","footer.status":"Matsayi","form.sending":"Ana aikawa…","form.failed":"Hakan bai yi aiki ba: ku sake gwadawa daga baya.","form.offline":"Ba a iya isa ga AI-gile ba: ku sake gwadawa daga baya.","interest.title":"AI-gile: ku sanar da ni idan alpha ya buɗe","interest.description":"Ku bar imel ɗinku don jin lokacin da alpha ko beta na AI-gile a rufe zai buɗe.","interest.h1":"🔔 Ku sanar da ni idan ya buɗe","interest.lede":"AI-gile yana pre-alpha a rufe. Ku bar imel ɗinku za mu rubuto sau ɗaya, idan akwai wuri a gare ku.","interest.email":"Imel ɗinku","interest.which":"Wane gwaji?","interest.alpha":"Alpha a rufe: da wuri, mai tsauri, sauye-sauye da yawa","interest.beta":"Beta: ya fi tsayawa, daga baya","interest.both":"Duk ɗaya, wanda ya fara zuwa","interest.submit":"Saka ni cikin jerin","interest.thanks":"Na gode! Kuna cikin jerin.","interest.kept":"Imel ɗinku da gwajin da kuka zaɓa kaɗai ake riƙewa, don wannan jerin kawai. Babu jaridar imel, babu masu bin diddigi.","licence.title":"AI-gile: lasisin kasuwanci","licence.description":"Kuna amfani da AI-gile a kasuwancinku? Ku nemi lasisin kasuwanci kyauta.","licence.h1":"📜 Lasisin kasuwanci","licence.lede":"Kuna amfani da AI-gile a wurin aiki? Ku gaya mana ko ku wane ne da abin da kuke yi. Idan yana yin alheri, lasisin kyauta ne.","licence.company":"Kamfani","licence.website":"Shafin yanar gizo","licence.what":"Abin da kuke yi","licence.how":"Yadda yake taimakon duniya","licence.email":"Imel","licence.submit":"Nema","licence.thanks":"Na gode! Za mu amsa ta imel.","status.title":"Matsayin AI-gile","status.h1":"Matsayin AI-gile","status.quiet":"Komai lafiya","status.checking":"Ana dubawa…","status.offline":"Ba a iya isa ga sabis ɗin matsayi yanzu (ana sake gwadawa)","status.updated":"an sabunta {ago}","status.justNow":"yanzu-yanzu","status.min":"mintuna {n} da suka wuce","status.hours":"awa {n} da ta wuce","status.days":"kwana {n} da suka wuce","live.h2":"Kalli yadda ake gina shi, kai tsaye","live.caption":"An ɓoye kowane kati: kana ganin siffar aikin, ba kalmomin ba.","live.watching.one":"kai tsaye: {n} na kallo","live.watching.other":"kai tsaye: {n} na kallo","live.offline":"Allon kai tsaye yana hutawa kaɗan. Ka sake dubawa nan ba da jimawa ba.","live.cols":"Backlog|A yi|Ana yi|Ƙungiya na dubawa|Don a gwada|Don ƙungiya|An gama","live.last.now":"An motsa katin ƙarshe yanzu-yanzu","live.last.min.one":"An motsa katin ƙarshe mintuna {n} da suka wuce","live.last.min.other":"An motsa katin ƙarshe mintuna {n} da suka wuce","live.last.hour.one":"An motsa katin ƙarshe awa {n} da ta wuce","live.last.hour.other":"An motsa katin ƙarshe awanni {n} da suka wuce","live.last.day.one":"An motsa katin ƙarshe rana {n} da ta wuce","live.last.day.other":"An motsa katin ƙarshe kwanaki {n} da suka wuce"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Mutummutumai.","Wakilta."]},{"n":2,"texts":["Mutummutumi kanban.","Wakilai tsararru.","Ra'ayoyi, gini."]},{"n":3,"texts":["Kanban don mutummutumai.","Ra'ayoyi su zama fasali.","Kanban na wakilai, kyauta."]},{"n":5,"texts":["Allon kanban da wakilai ke tafiyarwa.","Ku rubuta kati. Wakilai su gina.","Kyauta, na gida, ɗan wasa."]},{"n":8,"texts":["Allon kanban kyauta inda wakilan AI ke aiki.","Rubuta ra'ayi. Wakilai su gina shi. Ku karɓa.","Agile don mutum ɗaya da mutummutumai masu haƙuri da yawa."]},{"n":13,"texts":["Allon kanban a kwamfutarku inda wakilan AI ke ɗaukar katunan aiki.","Rubuta ra'ayi. Ƙungiyar wakilai ta gina shi. Mai gwaji ya duba.","Kyauta, babu asusu ko masu bin diddigi: allo, wasu mutummutumai, kuma ku ne shugaba."]},{"n":21,"texts":["AI-gile allon kanban ne don aiki da wakilan AI masu rubuta lamba. Su ke ɗaukar katunan; ku kuwa kuna gwadawa da karɓa.","Kowane aiki yana samun jagora da ƙungiyar wakilan AI. Ku yi sharhi a kowane kati sai ƙungiyar ta fara aiki.","Allon ayyuka na kai, kyauta, mai aiki a kwamfutarku. Ma'aikata mutummutumai ne. Wanda ke cewa eh, ku ne."]},{"n":34,"texts":["Kuna sa ra'ayoyi a allo. Ƙungiyar wakilan AI tana mayar da su fasalolin da ke aiki, tana gwada su, ta mayar muku da su tare da matakan gwadawa. Babu abin da ake ƙirgawa an gama sai kun faɗa.","AI-gile allon kanban ne na gida da Rich ya gina da taimako mai yawa daga wakilan da yake gudanarwa yanzu. Kyauta ne, yana aiki a kwamfutarku, ana raba shi da abokai, ba a sayarwa ba.","Ku yi tunanin allon kanban na yau da kullum, da ginshiƙai daga Backlog zuwa An gama, amma wakilan AI ne ke ɗaukar katunan. Suna ba da rahoton ci gaba, suna tambaya idan sun makale, kuma kullum suna jiran yardarku."]},{"n":55,"texts":["AI-gile allon kanban ne inda ƙungiyar ta kunshi wakilan AI. Kowane aiki yana da jagora da ke tsara aikin da masu taimako da ke gina shi. Idan fasali ya shirya, mai gwajin AI yana gwada shi ya ɗauki hoton allo, sannan ya isa tarinku. Ku karɓa, ko ku yi sharhi su sake yi.","Ya fara ne a matsayin hanyar mutum ɗaya na bin zaman rubuta lamba na AI da yawa lokaci guda, sannan ya girma ya zama allo na gaske. Yana aiki a injin ɗinku, ba ya buƙatar asusu, kuma ba shi da masu bin diddigi. Haka kuma ba a gama ba, don haka ku sa ran gefuna masu tsauri da wani abin mamaki.","Ga sigar gaskiya. Har yanzu dole ne ku kasance da ra'ayoyin, kuma dole ne ku duba sakamakon. Abin da AI-gile ke yi shi ne duk abin da ke tsakanin: yana tsara katunan, yana tashe wakilin da ya dace idan kun yi sharhi, yana nuna daidai abin da ya canza, kuma yana tara komai a ɗan gajeren tari a gare ku."]},{"n":89,"texts":["AI-gile allon kanban ne kyauta da kuke gudanarwa a kwamfutarku. Maimakon mutane, kowane aiki yana da ƙungiyar wakilan AI: jagora da ke mayar da ra'ayoyinku kati da shiri, da masu taimako da ke ɗaukar katunan bisa fifiko. Idan an gina wani abu, mai gwajin AI yana bin matakan gwaji ya nuna muku abin da ya gani. Sannan yana jira a tari ɗaya mai suna Gare ku. Kuna karɓa, ko ku yi sharhi ƙungiyar ta sake gwadawa. Babu abin da ke isa An gama ba tare da ku ba.","Akwai wasu siffofi da ba za ku yi tsammani ba. Tsaron dare yana cika ginshiƙin A yi yayin da kuke barci, yana zaɓar katunan da ba sa buƙatar amsarku. Na'urar ƙidayar token tana nuna yawan da wakilai suka yi amfani da shi yau da wannan mako, kuma Yanayin Babu Token yana gaya musu su daina kashewa. Kuna iya aika saƙo ga abokai, kuma saƙonnin sirri an ɓoye su daga ƙarshe zuwa ƙarshe. Allon yana magana da harsuna kusan 120, ciki har da Dutch, Flemish, na 'yan fashin teku da Klingon. Babu ɗaya daga cikinsu da ke da farashi, kuma babu wanda ke ƙoƙarin sayar muku.","AI-gile ƙaramin aiki ne na kai, ba kamfani ba. Rich yana son kula da ayyukan rubuta lamba na AI da yawa ba tare da buɗe kowace manhaja ya duba ba, don haka shi da wakilai suka gina allo don haka, sannan suka yi amfani da allon wajen gina sauran. Yana pre-alpha a rufe, ma'ana yana aiki, galibi, ga ɗimbin abokai. Babu shafin farashi, babu jaridar imel, babu shirin girma. Idan ya yi kama da mai amfani, kuna iya neman gwadawa idan ya buɗe kaɗan."]},{"n":144,"texts":["AI-gile allon kanban ne don mutum ɗaya da wakilan AI da yawa. Yana aiki a kwamfutarku kuma kyauta ne gaba ɗaya. Kuna ƙara ayyuka, kuma kowane aiki yana samun jagora da ƙaramar ƙungiya. Kuna hira da jagora, kamar Discord, kuna kwatanta ra'ayi; jagora yana mayar da shi kati da shiri, sannan yana jiran ku danna Go. Ƙungiyar tana aiki ta cikin katunan bisa fifiko, da layin umarni mai sauƙi da aka yi wa samfuran harshe. Kafin wani abu ya dawo gare ku, mai gwajin AI yana bin matakai a kwafin manhajar ya haɗa hoton allo. Aikin da aka gama yana isa tarinku tare da fayilolin da suka canza da bambancin. Kuna karɓa, ko ku bar sharhi ƙungiyar ta farka ta sake gwadawa. Ku kaɗai ne za ku iya matsar da kati zuwa An gama.","Kwana ɗaya da AI-gile, kusan. Da yamma kuna barin sharhi kaɗan: wannan maɓalli yana wurin da bai dace ba, ya kamata a jera wancan jerin, za mu iya samun yanayin duhu. Kuna kwanciya barci. Wakilai suna karanta sharhin, suna yin sauye-sauyen, suna gwada su, suna mayar muku. Idan A yi ya ƙare, tsaron dare yana cika shi daga backlog da katunan da ba sa buƙatar amsarku. Da safe akwai tari ɗaya gajere: tambayoyi biyu da abubuwan gwadawa kaɗan, kowanne da matakan da mai barci zai iya bi da hoton allo na yana aiki. Kuna danna, kuna karɓar masu kyau, kuna mayar da sauran. Na'urar ƙidayar token tana nuna abin da aka yi amfani da shi, kuma Yanayin Babu Token yana nan don makonni masu sauƙi. Sannan kuna karin kumallo, wanda wakilai ba za su iya taimako a kai ba tukuna.","Da farko, abin da AI-gile ba shi ba. Ba kamfanin farawa ba ne, ba na sayarwa ba, kuma babu wanda ke tattara bayananku. Allo ne kyauta da ke aiki a kwamfutarku, babu asusu, babu masu bin diddigi, babu kuki. Abin da yake shi ne: wuri ɗaya mai tsabta don ganin duk ayyukan rubuta lamba na AI a lokaci guda, da ƙungiyar wakilai suna yin katunan, ku kuma kuna yanke shawara. Yana haɗa katunan masu alaƙa, yana gyara taken da suka ruɗe, kuma yana lura da yadda lamba take zama marar nauyi. Yana magana da harsuna kusan 120, daga Dutch da Flemish zuwa na 'yan fashin teku da Klingon. Abokai za su iya aika wa juna saƙo, a sirri kuma a ɓoye. Rich da wakilai masu haƙuri da yawa ne suka gina shi, galibi suna amfani da shi da kansa. Yana pre-alpha a rufe, don haka akwai tsauri a wurare. Idan ya yi kama da nishaɗi, ku nemi da ladabi kuma wataƙila ku shiga da wuri."]}],"quips":{"1":"Kalma ɗaya. Jarumtaka. Wataƙila ta wuce kima.","3":"Kalmomi uku. Sun fi gaskiya fiye da yawancin shafukan samfura.","8":"Kalmomi takwas. Har yanzu sun fi taro gajarta.","21":"Tsawon kalmomi maki na labari ne, ta hanya. Ai haka ne.","55":"Kalmomi hamsin da biyar. An gama katuna biyu yayin da kuke karanta wannan.","144":"Wannan shi ne dogon. Babu 233. Wakilai sun tafi barci."}},"timeline":{"first-idea.name":"Ra'ayin farko","first-idea.line":"Tattaunawa ta farko, kafin wata lamba ta wanzu.","first-board.name":"Allo na farko","first-board.line":"Allon da ke bin diddigin ginin kansa: katuna, ginshiƙai, ja da sauke, ayyuka.","team-roles.name":"Ƙungiya da matsayi","team-roles.line":"Bayanan wakilai, samfuran ƙungiya, wurare da wanda ke yin me.","install.name":"Shigarwa da fitarwa","install.line":"Zip da aboki zai iya shigarwa, sabuntawa kai-tsaye, hanyoyi da komawa baya.","usage-saver.name":"Tanadin amfani","usage-saver.line":"Auna abin da gudanarwa ke ci, kiyaye lamba marar nauyi, ajiye iyakarku.","friends.name":"Abokai da rabawa","friends.line":"DM na sirri, na'urar isar da saƙo a ɓoye, gayyata, matsayi da ayyukan da aka raba.","languages.name":"Harsuna","languages.line":"Kowane rubutun allo a cikin fayil na harshe, Dutch da Flemish na farko.","ai-tester.name":"Mai gwajin AI","ai-tester.line":"Mai gwaji yana duba kowace miƙawa tukuna kuma yana nuna abin da ya gani.","website.name":"Shafin yanar gizo","website.line":"aigile.lol, gwaji na farko da wannan jerin lokaci.","streaming.name":"Hira da yawo","streaming.line":"Discord, Twitch, OBS, yanayin mai yawo, GIF da emoji.","no-ai.name":"Fitowar babu AI","no-ai.line":"Allo ga masu rubuta lamba babu AI, da allunan jama'a.","night-watch.name":"Tsaron dare","night-watch.line":"Mai tsaro da Scrum Master suna kiyaye ƙungiyoyi a kan aiki yayin da kuke barci.","p-more.name":"Duk sauran","p-more.line":"Ƙananan ra'ayoyi da ke jiran lokacinsu.","p-android.name":"Waya da Android","p-android.line":"Isa allonku daga waya, sannan manhajar Android ta asali.","p-release.name":"Alpha da bayansa","p-release.line":"Alpha a rufe, shafin kai-tsaye, sannan beta.","p-languages.name":"Ƙarin harsuna","p-languages.line":"Fiye da harsuna ɗari, da yanayin nutsewa ga masu koyo.","p-engines.name":"Ƙarin injunan AI","p-engines.line":"Zaɓi Claude, Codex ko Gemini ga kowane wakili.","p-pro.name":"Aikin ƙwararru","p-pro.line":"Alamomin haɗari, ƙofofin haɗawa, katunan faruwa da shingaye.","p-self.name":"Kula da ku","p-self.line":"Yanayin gajiya, tunatarwar kula da kai da 4:20.","p-servers.name":"Sabobi da girma","p-servers.line":"Saitunan sabar na duniya, matsayi da tsara girma.","p-livestream.name":"Ƙarin yawo","p-livestream.line":"Hirar Twitch, emoji na kai da kallon kai-tsaye na jama'a."}};
